// Eldra Account identity schema -- .github/docs/architecture/ownership-and-permissions.md
// §6.1/§6.2/§12 Phase 1. Provisions the three collections that make
// Principal.accountId provider-neutral:
//
//   eldra_accounts         an Eldra-owned identity that owns things, holds
//                          memberships, and is the subject of every
//                          permission decision (§6.1). Its `id` is
//                          generated by Eldra and is NEVER a Directus
//                          user id.
//   eldra_identity_links   (provider, provider_subject) -> account (§6.2).
//                          During Beta the only provider is 'directus';
//                          external providers are added as new rows, not
//                          as schema changes.
//   eldra_platform_grants  an explicit, Eldra-owned platform capability
//                          grant. This is what replaces the implicit
//                          "Directus admin_access means Eldra platform
//                          administrator" derivation resolvePrincipal
//                          used to perform.
//
// WHY THESE LIVE IN DIRECTUS DURING BETA. The identity MODEL is Eldra's
// (Eldra-generated ids, (provider, provider_subject) as the only identity
// key, capabilities granted by row). The identity STORE is Directus's
// PostgreSQL, reached through the same REST adapter every other collection
// uses -- which keeps reads and writes inside Directus's own cache
// invalidation (CACHE_AUTO_PURGE fires on ItemsService mutations only; the
// stale-read class of bug server/utils/character-resource-atomic.ts
// documents comes precisely from writing AROUND Directus), and requires no
// new database credential or grant to deploy. server/utils/eldra-accounts.ts
// is the single module that knows these collections exist; swapping to a
// direct-PostgreSQL adapter (the `pg` precedent in
// server/utils/character-resource-atomic.ts) means rewriting that one file.
//
// COMPOSITE UNIQUENESS. Directus's Fields API only supports single-column
// uniqueness (the same limitation create-world-memberships-schema.mjs and
// create-rules-packages-schema.mjs both hit). The two composite keys that
// MUST be enforced by the database rather than by application courtesy --
// (provider, provider_subject) and (account_id, capability) -- are
// therefore each stored additionally as one canonical, unique string
// column (`identity_key`, `grant_key`). The application never parses those
// columns; it only ever computes them (see eldra-accounts.ts's
// buildIdentityKey/buildGrantKey) so a concurrent double-insert fails at
// the database, not silently.

const DIRECTUS_URL =
  process.env.DIRECTUS_URL ||
  process.env.NUXT_PUBLIC_DIRECTUS_URL ||
  'https://directus.theledouxs.com'

const DIRECTUS_TOKEN =
  process.env.DIRECTUS_SCHEMA_TOKEN ||
  process.env.DIRECTUS_TOKEN ||
  process.env.NUXT_DIRECTUS_TOKEN ||
  process.env.NITRO_DIRECTUS_TOKEN ||
  ''

const ACCOUNTS = 'eldra_accounts'
const IDENTITY_LINKS = 'eldra_identity_links'
const PLATFORM_GRANTS = 'eldra_platform_grants'

if (!DIRECTUS_TOKEN) {
  console.error('Missing Directus token for schema migration.')
  process.exit(1)
}

async function dx(path, options = {}) {
  const res = await fetch(`${DIRECTUS_URL.replace(/\/$/, '')}${path}`, {
    ...options,
    headers: {
      Authorization: `Bearer ${DIRECTUS_TOKEN}`,
      'Content-Type': 'application/json',
      ...(options.headers || {})
    }
  })

  const text = await res.text()
  let json = null

  try {
    json = text ? JSON.parse(text) : null
  } catch {
    json = text
  }

  if (!res.ok) {
    const message = typeof json === 'string' ? json : JSON.stringify(json)
    throw new Error(`${res.status} ${res.statusText}: ${message}`)
  }

  return json
}

async function collectionNames() {
  const res = await dx('/collections')
  return new Set(
    (Array.isArray(res?.data) ? res.data : [])
      .map((row) => String(row?.collection || '').trim())
      .filter(Boolean)
  )
}

async function ensureCollection(collection, options = {}) {
  const names = await collectionNames()

  if (names.has(collection)) {
    console.log(`Collection exists: ${collection}`)
    return
  }

  const body = {
    collection,
    meta: {
      collection,
      icon: options.icon || 'settings_suggest',
      note: options.note || null,
      display_template: options.displayTemplate || null,
      hidden: false,
      singleton: false,
      accountability: 'all'
    },
    schema: {
      name: collection
    }
  }

  // Same reasoning as create-world-memberships-schema.mjs: Directus's
  // default (no explicit `fields` array) provisions an auto-incrementing
  // integer primary key, and the primary key type cannot be changed after
  // collection creation via /fields -- it must be declared here. Every
  // collection below is uuid-keyed, because an Eldra account id must not
  // be a guessable sequence.
  body.fields = [
    {
      field: 'id',
      type: 'uuid',
      meta: {
        hidden: true,
        interface: 'input',
        readonly: true,
        special: ['uuid']
      },
      schema: {
        is_primary_key: true,
        has_auto_increment: false,
        data_type: 'uuid',
        length: 36
      }
    }
  ]

  await dx('/collections', {
    method: 'POST',
    body: JSON.stringify(body)
  })

  console.log(`Created collection: ${collection}`)
}

async function fieldNames(collection) {
  const res = await dx(`/fields/${collection}`)

  return new Set(
    (Array.isArray(res?.data) ? res.data : [])
      .map((row) => String(row?.field || '').trim())
      .filter(Boolean)
  )
}

async function ensureField(collection, fieldDef) {
  const names = await fieldNames(collection)

  if (names.has(fieldDef.field)) {
    console.log(`Field exists: ${collection}.${fieldDef.field}`)
    return
  }

  await dx(`/fields/${collection}`, {
    method: 'POST',
    body: JSON.stringify(fieldDef)
  })

  console.log(`Created field: ${collection}.${fieldDef.field}`)
}

let sort = 1

function baseMeta(collection, field, interfaceName, note, extra = {}) {
  return {
    collection,
    field,
    interface: interfaceName,
    display: 'raw',
    hidden: false,
    readonly: false,
    sort: sort++,
    width: extra.width || 'half',
    note: note || null,
    required: extra.required === true
  }
}

function uuidField(collection, field, options = {}) {
  return {
    field,
    type: 'uuid',
    meta: baseMeta(collection, field, 'input', options.note, {
      required: options.required,
      width: options.width
    }),
    schema: {
      name: field,
      table: collection,
      data_type: 'uuid',
      is_nullable: options.required ? false : true,
      default_value: options.defaultValue ?? null
    }
  }
}

function stringField(collection, field, options = {}) {
  return {
    field,
    type: 'string',
    meta: baseMeta(collection, field, options.interface || 'input', options.note, {
      required: options.required,
      width: options.width
    }),
    schema: {
      name: field,
      table: collection,
      data_type: 'character varying',
      max_length: options.maxLength || 255,
      is_nullable: options.required ? false : true,
      is_unique: options.unique === true,
      default_value: options.defaultValue ?? null
    }
  }
}

function timestampField(collection, field, options = {}) {
  return {
    field,
    type: 'timestamp',
    meta: baseMeta(collection, field, 'datetime', options.note, {
      required: options.required,
      width: options.width
    }),
    schema: {
      name: field,
      table: collection,
      data_type: 'timestamp with time zone',
      is_nullable: options.required ? false : true,
      default_value: options.defaultValue ?? null
    }
  }
}

async function createSchema() {
  await ensureCollection(ACCOUNTS, {
    icon: 'account_circle',
    note: "An Eldra Account -- the provider-neutral identity Principal.accountId carries. Its id is generated by Eldra and is never a Directus user id; the Directus user it authenticates through is recorded in eldra_identity_links instead. See .github/docs/architecture/ownership-and-permissions.md §6.1.",
    displayTemplate: '{{display_name}}'
  })

  await ensureField(ACCOUNTS, stringField(ACCOUNTS, 'display_name', {
    required: true,
    note: 'Human-readable name. Display only -- no authorization decision anywhere reads it, and no account is ever matched or linked by it.'
  }))

  await ensureField(ACCOUNTS, stringField(ACCOUNTS, 'status', {
    required: true,
    defaultValue: 'active',
    note: 'active | suspended. Validated in application code, matching this project\'s convention for string-typed classification columns (entities.visibility, world_memberships.role).'
  }))

  await ensureField(ACCOUNTS, timestampField(ACCOUNTS, 'created_at', { required: true }))
  await ensureField(ACCOUNTS, timestampField(ACCOUNTS, 'updated_at', { required: true }))

  await ensureCollection(IDENTITY_LINKS, {
    icon: 'link',
    note: "Maps one external authentication identity to one Eldra Account (§6.2). The identity key is (provider, provider_subject) -- NEVER email, which is mutable, reassignable, frequently absent on this instance, and an account-takeover vector. Many links may point at one Account; adding a provider is a new row, not a schema change.",
    displayTemplate: '{{provider}}:{{provider_subject}}'
  })

  await ensureField(IDENTITY_LINKS, uuidField(IDENTITY_LINKS, 'account_id', {
    required: true,
    note: 'eldra_accounts.id -- the Eldra Account this external identity resolves to.'
  }))

  await ensureField(IDENTITY_LINKS, stringField(IDENTITY_LINKS, 'provider', {
    required: true,
    note: "Authentication provider. 'directus' is the only one during Beta; external providers (google, microsoft, ...) are deferred to a later phase and will be additional values here, never new columns. Never an input to any capability decision (§6.2 rule 4)."
  }))

  await ensureField(IDENTITY_LINKS, stringField(IDENTITY_LINKS, 'provider_subject', {
    required: true,
    note: "The provider's own stable subject for this identity -- a Directus user id for provider='directus'. Recorded here and nowhere else; this is the ONLY place a Directus user id survives after Phase 1."
  }))

  await ensureField(IDENTITY_LINKS, stringField(IDENTITY_LINKS, 'identity_key', {
    required: true,
    unique: true,
    maxLength: 512,
    note: "Canonical '<provider>|<provider_subject>'. Exists solely to give (provider, provider_subject) real database-level uniqueness, which Directus's Fields API cannot express as a composite constraint. Computed by server/utils/eldra-accounts.ts; never parsed."
  }))

  await ensureField(IDENTITY_LINKS, timestampField(IDENTITY_LINKS, 'linked_at', { required: true }))

  await ensureCollection(PLATFORM_GRANTS, {
    icon: 'admin_panel_settings',
    note: "One explicitly granted platform capability for one Eldra Account. This collection is what makes Eldra platform administration independent of Directus roles/policies: resolvePrincipal reads ONLY these rows for platform scope, and a Directus Administrator with no row here holds no Eldra platform capability. Granted deliberately via scripts/directus/bootstrap-eldra-platform-admin.mjs, never derived.",
    displayTemplate: '{{capability}}'
  })

  await ensureField(PLATFORM_GRANTS, uuidField(PLATFORM_GRANTS, 'account_id', {
    required: true,
    note: 'eldra_accounts.id -- the Account holding this grant.'
  }))

  await ensureField(PLATFORM_GRANTS, stringField(PLATFORM_GRANTS, 'capability', {
    required: true,
    note: "One PlatformCapability from server/utils/authorization.ts (e.g. platform.settings.manage). Unknown values are ignored at read time rather than trusted, so a stale or hand-edited row can never widen the capability vocabulary."
  }))

  await ensureField(PLATFORM_GRANTS, stringField(PLATFORM_GRANTS, 'grant_key', {
    required: true,
    unique: true,
    maxLength: 512,
    note: "Canonical '<account_id>|<capability>'. Gives (account_id, capability) real database-level uniqueness for the same reason identity_key does, so re-running the bootstrap script cannot create duplicate grants."
  }))

  await ensureField(PLATFORM_GRANTS, timestampField(PLATFORM_GRANTS, 'granted_at', { required: true }))

  console.log('Eldra Accounts schema is ready.')
}

createSchema().catch((error) => {
  console.error(error?.message || String(error))
  process.exit(1)
})
